(()=>{const Study=window.ChaoMotionStudy;if(document.body.classList.contains('motion-board')){document.querySelectorAll('[data-motion-study]').forEach(c=>new Study(c,Number(c.dataset.motionStudy)));return}
const studies=[...document.querySelectorAll('[data-motion-study]')].map(c=>new Study(c,Number(c.dataset.motionStudy)));const main=studies.find(s=>!s.mini);const data=[['Horizon','地平之外','大尺度环面缓慢起伏，像光穿过一件悬浮雕塑。移动指针改变观看角度，按下唤起波动。'],['Silk','银色流动','一张由细密光线织成的银色缎带，随时间翻转，随鼠标轻轻偏转。'],['Eclipse','寂静引力','两个天体交叠，细环围绕光源运行。鼠标改变光位，按下触发一次呼吸。'],['Monolith','光的秩序','以连续的金属光栅构成建筑般的体量。光线扫过时，结构逐层显现。'],['Contour','无形之境','等高线在空间中缓慢变形，构成介于地形与涟漪之间的抽象场。']];let chosenLogo=null,chosenMotion=null;try{const old=JSON.parse(localStorage.getItem('chao-design-study')||'{}');chosenLogo=old.logo||null;chosenMotion=old.motion||null}catch{}
function update(){document.querySelectorAll('[data-logo-choice]').forEach(b=>{const on=Number(b.dataset.logoChoice)===chosenLogo;b.setAttribute('aria-pressed',String(on));b.classList.toggle('selected',on)});document.querySelectorAll('[data-motion-choice]').forEach(b=>{const on=Number(b.dataset.motionChoice)===chosenMotion;b.setAttribute('aria-pressed',String(on));b.classList.toggle('selected',on)});document.querySelector('#chosen-logo').textContent=chosenLogo?'L0'+chosenLogo:'尚未选择';document.querySelector('#chosen-motion').textContent=chosenMotion?'M0'+chosenMotion:'尚未选择';document.querySelector('#copy-selection').disabled=!(chosenLogo&&chosenMotion);try{localStorage.setItem('chao-design-study',JSON.stringify({logo:chosenLogo,motion:chosenMotion}))}catch{}}
document.querySelectorAll('[data-logo-choice]').forEach(b=>b.addEventListener('click',()=>{chosenLogo=Number(b.dataset.logoChoice);document.querySelector('.study-brand img').src='assets/logo-options/logo-'+chosenLogo+'.svg';update()}));document.querySelectorAll('[data-motion-choice]').forEach(b=>b.addEventListener('click',()=>{chosenMotion=Number(b.dataset.motionChoice);const item=data[chosenMotion-1];main.setMode(chosenMotion);document.querySelector('#motion-number').textContent='0'+chosenMotion;document.querySelector('#motion-title').textContent=item[0];document.querySelector('#motion-description').textContent=item[2];document.querySelector('.study-hero').dataset.variant=String(chosenMotion);update()}));document.querySelector('#pause-study').addEventListener('click',function(){main.paused=!main.paused;this.setAttribute('aria-pressed',String(main.paused));this.textContent=main.paused?'继续播放 ▷':'暂停 Ⅱ'});document.querySelector('#reset-selection').addEventListener('click',()=>{chosenLogo=null;chosenMotion=null;document.querySelector('.study-brand img').src='assets/chao-logo.svg?v=l05';document.querySelector('#copy-selection').textContent='复制我的选择 ↗';update()});document.querySelector('#copy-selection').addEventListener('click',async function(){const result='我选择 Logo L0'+chosenLogo+'，动态封面 M0'+chosenMotion+'，请应用到正式网站。';try{await navigator.clipboard.writeText(result);this.textContent='选择已复制 ✓'}catch{document.querySelector('#selection-text').textContent=result}});if(chosenLogo)document.querySelector('.study-brand img').src='assets/logo-options/logo-'+chosenLogo+'.svg';if(chosenMotion){main.setMode(chosenMotion);document.querySelector('#motion-title').textContent=data[chosenMotion-1][0];document.querySelector('#motion-number').textContent='0'+chosenMotion;document.querySelector('#motion-description').textContent=data[chosenMotion-1][2]}update();})();
